import{artworkKey,newsArtworkCanvas}from './news-artwork.mjs';
import{picture,textLines,canvasBlob,saveBlob,shareFile}from './visual-export.mjs';
export async function shareNewsImage({post,state,element,button,busy,signedImage}){if(!post.published||post.deleted_at)throw Error('مشاركة الصور للأخبار المنشورة والمتاحة فقط');const d=element('dialog',undefined,'news-share-preview');d.append(element('h2','مشاركة الخبر كصورة'),element('p','اختر تطبيق التواصل من نافذة المشاركة، أو احفظ الصورة لإرسالها.'));const status=element('p','جاري تجهيز الصورة…');d.append(status,button('إغلاق',()=>{d.close();d.remove()}));document.body.append(d);d.showModal();try{const family=JSON.parse(localStorage.getItem('family-selection')||'null'),c=document.createElement('canvas');c.width=1080;c.height=100;let ctx=c.getContext('2d');ctx.font='bold 36px sans-serif';const title=textLines(ctx,post.title,960);ctx.font='28px sans-serif';const body=textLines(ctx,post.body,960);const paths=post.image_paths?.length?post.image_paths:post.image_path?[post.image_path]:[];let image=null,logo=null;if(paths[0])image=await picture(await signedImage(paths[0]));try{logo=await picture(family?.logo||(family?.code==='01'?'/family-logo.png':'/platform-logo.png'))}catch{}if(artworkKey(post)){image?.close();image=await newsArtworkCanvas(post,{signedImage})}if(post.artwork_only&&image&&!image.artworkTruncated){const blob=await canvasBlob(image);if(!d.open)return;const url=URL.createObjectURL(blob),preview=element('img');preview.src=url;preview.alt=post.title;d.append(preview,button('مشاركة عبر التطبيقات',()=>busy(null,()=>shareFile(blob,'family-news-'+post.id+'.jpg')),'primary'),button('حفظ صورة الخبر',()=>saveBlob(blob,'family-news-'+post.id+'.jpg'),'secondary'));status.remove();d.addEventListener('close',()=>URL.revokeObjectURL(url));return d}c.height=220+(image?1080:0)+title.length*48+body.length*40+140;ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.direction='rtl';ctx.textAlign='right';ctx.fillStyle='#123747';ctx.font='bold 32px sans-serif';ctx.fillText(family?.name||'منصة العوائل',1020,65);ctx.fillStyle='#536575';ctx.font='24px sans-serif';ctx.fillText(post.profiles?.display_name||state.profile?.display_name||'أخبار العائلة',1020,110);if(logo){const scale=Math.min(220/logo.width,100/logo.height);ctx.drawImage(logo,60,35,logo.width*scale,logo.height*scale);logo.close()}let y=170;if(image){const scale=Math.min(1080/image.width,1080/image.height);ctx.fillStyle='#f4f6f8';ctx.fillRect(0,y,1080,1080);ctx.drawImage(image,(1080-image.width*scale)/2,y+(1080-image.height*scale)/2,image.width*scale,image.height*scale);image.close?.();y+=1130}ctx.fillStyle='#142b39';ctx.font='bold 36px sans-serif';for(const line of title){ctx.fillText(line,1020,y);y+=48}y+=20;ctx.font='28px sans-serif';for(const line of body){ctx.fillText(line,1020,y);y+=40}ctx.fillStyle='#71808b';ctx.font='22px sans-serif';ctx.fillText('خبر رقم '+post.id+' · '+new Date(post.created_at).toLocaleDateString('ar-SA'),1020,c.height-45);const blob=await canvasBlob(c);if(!d.open||!d.isConnected)return;const url=URL.createObjectURL(blob),preview=element('img');preview.src=url;preview.alt='معاينة صورة الخبر';d.append(preview);status.remove();d.append(button('مشاركة عبر التطبيقات',()=>busy(null,async()=>{try{await shareFile(blob,'family-news-'+post.id+'.jpg')}catch(e){if(e.name!=='AbortError')throw e}}),'primary'),button('حفظ صورة الخبر',()=>saveBlob(blob,'family-news-'+post.id+'.jpg'),'secondary'));d.addEventListener('close',()=>URL.revokeObjectURL(url))}catch(e){status.textContent=e.message}return d}
